1	/* Wishweave Wonders — shared namespace, tuning values and small utilities.
2	   Loaded first. Every game script attaches to globalThis.WW so the same files
3	   run in the browser, the Android WebView and Node unit tests. */
4	(function (WW) {
5	  'use strict';
6	
7	  WW.VERSION = '1.0.0';
8	  WW.DESIGN = { w: 841, h: 1870 };
9	  WW.PLATES = WW.PLATES || {};
10	
11	  /* Gameplay timing in seconds and speeds in metres/second. The values marked
12	     "spec" come from docs/LEVEL1-GAMEPLAY-SPEC.md; the rest are tuning targets
13	     checked by tests/unit and tests/e2e. */
14	  WW.TUNING = {
15	    countdown: 3,
16	    purlSpeed: 5.0,
17	    purlAccel: 9,                 // m/s² when starting/stopping
18	    laneChangeTime: 0.22,
19	    jumpTime: 0.68,
20	    jumpAirborneAbove: 0.3,       // jump height fraction that clears Snagling's contact
21	    inputBufferTime: 0.15,        // swipe-up within this time before landing is replayed
22	
23	    snagRevealToContact: 0.55,    // spec: visible reveal to possible contact
24	    snagContactWindow: 0.10,      // contact is tested for this long after the hop lands
25	    snagTangle: 0.5,              // spec: ankle tangle duration
26	    hitImmunity: 1.6,             // spec: post-hit damage immunity
27	    slowAfterHit: 0.6,            // speed multiplier while recovering footing
28	    slowAfterHitTime: 1.2,
29	    snagRetreat: 1.4,
30	    dropAheadF: 0.10,             // dropped thread lands this far ahead (path fraction)
31	    dropSpacingF: 0.07,
32	    recoveryLoopTime: 2.6,        // local loop that returns Purl to the landing entry
33	    failDelay: 1.2,
34	
35	    ribbonUnfurl: 1.3,
36	    shortcutUnroll: 1.5,
37	    tasselLift: 0.45,
38	    tasselStagger: 0.3,
39	    butterflyEmerge: 0.7,
40	    butterflyFly: 1.7,
41	    butterflyPlace: 0.45,
42	    routeSettle: 0.25,            // pause after an opening completes before Purl moves
43	
44	    pickupRadiusF: 0.035,         // path-fraction tolerance for collecting a thread
45	    dropPickupLane: 0.6,          // |lane - dropLane| must be below this to recover a drop
46	    cueRepeatAfter: 4,
47	
48	    loopSpeed: 5.0,
49	    loopSpeedJitter: 0.04,
50	    loopReact: [0.45, 1.3],
51	    loopHesitateChance: 0.22,
52	    loopHesitate: [0.5, 1.2],
53	    loopHopMissChance: 0.3,
54	    loopStumble: 0.9,
55	    loopDropOnStumbleChance: 0.35,
56	    loopRecover: 1.4,
57	
58	    finishWaitForLoop: 25
59	  };
60	
61	  /* Deterministic PRNG (mulberry32). Only the race simulation consumes it. */
62	  WW.rng = function (seed) {
63	    let a = (seed >>> 0) || 1;
64	    const next = function () {
65	      a = (a + 0x6D2B79F5) >>> 0;
66	      let t = a;
67	      t = Math.imul(t ^ (t >>> 15), t | 1);
68	      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
69	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
70	    };
71	    return {
72	      next: next,
73	      range: function (lo, hi) { return lo + (hi - lo) * next(); },
74	      chance: function (p) { return next() < p; },
75	      pick: function (list) { return list[Math.floor(next() * list.length)]; }
76	    };
77	  };
78	
79	  WW.util = {
80	    clamp: function (v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; },
81	    lerp: function (a, b, t) { return a + (b - a) * t; },
82	    smooth: function (t) { t = t < 0 ? 0 : t > 1 ? 1 : t; return t * t * (3 - 2 * t); },
83	    easeOutBack: function (t) { const c = 1.70158; t -= 1; return 1 + (c + 1) * t * t * t + c * t * t; },
84	    approach: function (value, target, maxDelta) {
85	      return value < target ? Math.min(value + maxDelta, target) : Math.max(value - maxDelta, target);
86	    },
87	    /* Critically damped follow, frame-rate independent. */
88	    damp: function (value, target, halfLife, dt) {
89	      return target + (value - target) * Math.pow(2, -dt / Math.max(halfLife, 1e-4));
90	    }
91	  };
92	})(globalThis.WW = globalThis.WW || {});
93

1	/* Route geometry shared by the simulation, renderer and authoring tools.
2	
3	   A path is an array of control points [x, y, w, lane] in plate design pixels
4	   (841 × 1870):
5	     x, y  foot point of the lane centre (bottom-centre sprite anchor)
6	     w     the racer's on-screen sprite width at that point (depth scale)
7	     lane  horizontal distance in plate pixels between adjacent lanes (0 = single file)
8	
9	   Positions are smoothed with a Catmull-Rom spline. The path parameter f (0..1)
10	   is proportional to distance measured in racer widths (∫ |dp| / w), so a racer
11	   moving at a constant world speed covers equal f per second whether the path is
12	   near the camera or far away. Fractions in plate data always use this metric. */
13	(function (WW) {
14	  'use strict';
15	  const SUB = 12;
16	  const cache = new WeakMap();
17	
18	  function catmull(p0, p1, p2, p3, t) {
19	    const t2 = t * t, t3 = t2 * t;
20	    return 0.5 * ((2 * p1) + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 + (-p0 + 3 * p1 - 3 * p2 + p3) * t3);
21	  }
22	
23	  function prepare(points) {
24	    let prepared = cache.get(points);
25	    if (prepared) return prepared;
26	    if (!points || points.length < 2) throw new Error('A path needs at least two points');
27	    const n = points.length, dense = [];
28	    const at = function (i) { return points[Math.max(0, Math.min(n - 1, i))]; };
29	    for (let i = 0; i < n - 1; i++) {
30	      const p0 = at(i - 1), p1 = at(i), p2 = at(i + 1), p3 = at(i + 2);
31	      for (let k = 0; k < SUB; k++) {
32	        const t = k / SUB;
33	        dense.push([
34	          catmull(p0[0], p1[0], p2[0], p3[0], t),
35	          catmull(p0[1], p1[1], p2[1], p3[1], t),
36	          p1[2] + (p2[2] - p1[2]) * t,
37	          (p1[3] || 0) + ((p2[3] || 0) - (p1[3] || 0)) * t
38	        ]);
39	      }
40	    }
41	    const last = points[n - 1];
42	    dense.push([last[0], last[1], last[2], last[3] || 0]);
43	    const cum = [0];
44	    for (let i = 1; i < dense.length; i++) {
45	      const a = dense[i - 1], b = dense[i];
46	      const len = Math.hypot(b[0] - a[0], b[1] - a[1]) / Math.max(1, (a[2] + b[2]) / 2);
47	      cum.push(cum[i - 1] + len);
48	    }
49	    const total = cum[cum.length - 1] || 1;
50	    prepared = { dense: dense, cum: cum.map(function (c) { return c / total; }), widths: total };
51	    cache.set(points, prepared);
52	    return prepared;
53	  }
54	
55	  /* Returns {x, y, w, lane, tx, ty, f}; (tx, ty) is the unit direction of travel. */
56	  function sample(points, f) {
57	    const p = prepare(points);
58	    f = f < 0 ? 0 : f > 1 ? 1 : f;
59	    const cum = p.cum, d = p.dense;
60	    let lo = 0, hi = cum.length - 1;
61	    while (hi - lo > 1) {
62	      const mid = (lo + hi) >> 1;
63	      if (cum[mid] <= f) lo = mid; else hi = mid;
64	    }
65	    const span = cum[hi] - cum[lo] || 1;
66	    const t = (f - cum[lo]) / span;
67	    const a = d[lo], b = d[hi];
68	    let tx = b[0] - a[0], ty = b[1] - a[1];
69	    const len = Math.hypot(tx, ty) || 1;
70	    return {
71	      x: a[0] + (b[0] - a[0]) * t,
72	      y: a[1] + (b[1] - a[1]) * t,
73	      w: a[2] + (b[2] - a[2]) * t,
74	      lane: a[3] + (b[3] - a[3]) * t,
75	      tx: tx / len, ty: ty / len, f: f
76	    };
77	  }
78	
79	  /* Path fraction of the point on the path closest to (x, y). */
80	  function project(points, x, y) {
81	    const p = prepare(points);
82	    let best = 0, bestD = Infinity;
83	    for (let i = 0; i < p.dense.length; i++) {
84	      const q = p.dense[i];
85	      const d = (q[0] - x) * (q[0] - x) + (q[1] - y) * (q[1] - y);
86	      if (d < bestD) { bestD = d; best = i; }
87	    }
88	    return p.cum[best];
89	  }
90	
91	  /* Foot point for a racer at fraction f, lane value laneX (-1..1, continuous)
92	     and jump height fraction jumpH (0..1). Lanes offset horizontally. */
93	  function racerPoint(points, f, laneX, jumpH) {
94	    const s = sample(points, f);
95	    return {
96	      x: s.x + (laneX || 0) * s.lane,
97	      y: s.y - (jumpH || 0) * s.w * 0.42,
98	      groundY: s.y,
99	      w: s.w, tx: s.tx, ty: s.ty, f: s.f
100	    };
101	  }
102	
103	  /* Length of the path in racer widths; useful when choosing segment lengths. */
104	  function widths(points) { return prepare(points).widths; }
105	
106	  WW.path = { prepare: prepare, sample: sample, project: project, racerPoint: racerPoint, widths: widths };
107	})(globalThis.WW = globalThis.WW || {});
